@if(!($hasConsentChoice??false))<aside x-data="{open:true,custom:false,analytics:false,marketing:false,preferences:false,saving:false}" x-show="open" x-cloak class="fixed bottom-0 inset-x-0 z-[1000] bg-slate-950 text-white shadow-2xl" aria-label="Privacy preferences"><div class="max-w-6xl mx-auto p-5"><div class="flex flex-col lg:flex-row gap-5 justify-between"><div><h2 class="font-bold text-lg">Privacy choices</h2><p class="text-sm text-slate-300 mt-1">Necessary cookies keep the site secure. Optional analytics and marketing technologies are used only with your choice.</p></div><div class="flex flex-wrap gap-2"><button @click="save(false,false,false,'reject_optional')" class="btn btn--secondary">Reject optional</button><button @click="custom=!custom" class="btn btn--secondary">Customize</button><button @click="save(true,true,true,'accept_all')" class="btn btn--primary">Accept all</button></div></div><div x-show="custom" class="mt-4 grid sm:grid-cols-4 gap-3 text-sm"><label><input type="checkbox" checked disabled> Necessary</label><label><input type="checkbox" x-model="analytics"> Analytics</label><label><input type="checkbox" x-model="marketing"> Marketing</label><label><input type="checkbox" x-model="preferences"> Preferences</label><button @click="save(analytics,marketing,preferences,'customize')" class="btn btn--primary">Save choices</button></div></div><script>function consentRequest(a,m,p,action){return fetch(@json(route('consent.store')),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({analytics:a,marketing:m,preferences:p,action})})}</script><span x-init="save=async(a,m,p,action)=>{saving=true;const r=await consentRequest(a,m,p,action);saving=false;if(r.ok)open=false}"></span></aside>@endif